function free(x,y,r=.2){return cell(x-r,y-r)===0&&cell(x+r,y-r)===0&&cell(x-r,y+r)===0&&cell(x+r,y+r)===0}
function updateUI(){let g=game;$('#playerName').textContent=g.name;$('#classLine').textContent=`${g.job.toUpperCase()} · LV ${g.level}`;$('#hpText').textContent=`${Math.ceil(g.hp)} / ${g.maxHp}`;$('#hpBar').style.width=`${Math.max(0,g.hp/g.maxHp*100)}%`;$('#mpText').textContent=`${Math.ceil(g.mp)} / ${g.maxMp}`;$('#mpBar').style.width=`${Math.max(0,g.mp/g.maxMp*100)}%`;$('#xpText').textContent=`${g.xp} / ${g.nextXp}`;$('#xpBar').style.width=`${g.xp/g.nextXp*100}%`;$('#goldText').textContent=g.gold;$('#enemyText').textContent=g.entities.filter(e=>e.type==='enemy'||e.type==='boss').length;$('#weaponText').textContent=g.equipment.weapon?.name.toUpperCase()||'BARE HANDS';let left=g.entities.some(e=>e.type==='enemy'||e.type==='boss');$('#objective').textContent=left?tr('objective','CLEAR THE HALL'):(g.floor===100?tr('victory','THE TOWER IS YOURS'):tr('cleared','HALL CLEARED · FIND THE STAIR'))}
function mobStats(){let s=game.stats;return{damage:Math.round(9+s.Might*2+(game.equipment.weapon?.bonus||0)),defense:Math.round(s.Vitality*1.5+(game.equipment.armor?.bonus||0)),spell:Math.round(18+s.Intellect*3),crit:Math.min(45,5+s.Agility+game.stats.Luck)}}
