function dropLoot(){let def=pick(['weapon','armor','relic']),r=rarity[Math.min(4,Math.floor(Math.random()*5+game.floor/32))],item={...pick(definitions[def]),type:def,rarity:r,floor:game.floor};item.bonus=Math.floor(item.bonus*(1+game.floor*.023));game.inventory.push(item);game.gold+=8+game.floor*2;toast(`${item.rarity} ${item.name} found`);log(`Found ${item.name} · ${r}`);sound(610,.12,'triangle')}
function kill(e){game.entities=game.entities.filter(x=>x!==e);game.kills++;let xp=e.type==='boss'?120+game.floor*3:24+game.floor;gainXp(xp);game.gold+=e.type==='boss'?90:12;log(`${e.name} defeated · +${xp} XP`);if(e.type==='boss'||Math.random()<.42)dropLoot();updateUI()}
function attack(){if(!started||paused||modal||game.gameover||game.attackCd>0)return;game.attackCd=.42;let target=null,best=2.2;for(let e of game.entities){if(e.type!=='enemy'&&e.type!=='boss')continue;let dx=e.x-game.x,dy=e.y-game.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-game.ang;a=Math.atan2(Math.sin(a),Math.cos(a));if(d<best&&Math.abs(a)<.46){target=e;best=d}}sound(95,.07,'triangle',.045);if(target){let st=mobStats(),crit=Math.random()*100<st.crit,dmg=Math.round(st.damage*(crit?1.8:1));target.hp-=dmg;target.flash=.18;log(`${crit?'Critical! ':''}${target.name} −${dmg}`);if(target.hp<=0)kill(target);else sound(250,.05,'square',.02)}else{toast('Strike missed');}}
function cast(){if(game.mp<12||game.spellCd>0)return;game.mp-=12;game.spellCd=2.4;let hit=false;for(let e of [...game.entities]){if(e.type!=='enemy'&&e.type!=='boss')continue;let d=Math.hypot(e.x-game.x,e.y-game.y),a=Math.atan2(e.y-game.y,e.x-game.x)-game.ang;a=Math.atan2(Math.sin(a),Math.cos(a));if(d<5&&Math.abs(a)<.58){e.hp-=mobStats().spell;if(e.hp<=0)kill(e);hit=true}}sound(420,.22,'sine',.06);toast(hit?'ARCANE PULSE':'Focus gathered');updateUI()}
function interact(){if(!started||modal||paused)return;let target=null,dist=2;for(let e of game.entities){let d=Math.hypot(e.x-game.x,e.y-game.y),a=Math.atan2(e.y-game.y,e.x-game.x)-game.ang;a=Math.atan2(Math.sin(a),Math.cos(a));if(d<dist&&Math.abs(a)<.85){target=e;dist=d}}if(!target){toast('Nothing within reach');return}if(target.type==='npc')openNpc(target);else if(target.type==='chest'){if(target.opened){toast('The cache is empty');return}target.opened=true;game.gold+=30+game.floor*5;dropLoot();toast('Cache opened · shards secured');log('A sealed cache yielded treasure.');updateUI()}else if(target.type==='stairs'){if(game.entities.some(e=>e.type==='enemy'||e.type==='boss')){toast('The stair is sealed. Defeat every guardian.');return}if(game.floor===100){showEnd(true);return}game.floor++;if(game.floor%10===1)game.hp=Math.min(game.maxHp,game.hp+22);buildFloor();toast(`Ascending to floor ${game.floor}`);sound(330,.22,'sine')}}
