function openModal(type,html,title){modal=type;paused=true;$('#modalTitle').textContent=title||({inventory:'Inventory',status:'Character status',settings:'Settings',dialogue:'The wandering scribe',end:'The ascent'}[type]||type);$('#modalContent').innerHTML=html;$('#modalWrap').classList.add('open')}
function closeModal(){modal='';paused=false;$('#modalWrap').classList.remove('open');if(game.gameover)showEnd(game.won)}window.closeModal=closeModal;
function openInventory(){tab='gear';renderInventory();openModal('inventory',$('#modalContent').innerHTML,'Inventory & equipment')}
function renderInventory(){let gear=game.inventory.filter(i=>i.type===tab),equipped=game.equipment[tab];let h=`<div class="tabs">${['weapon','armor','relic'].map(t=>`<button class="tab ${tab===t?'active':''}" onclick="window.setTab('${t}')">${t.toUpperCase()}</button>`).join('')}<button class="tab" onclick="window.setTab('all')">ALL ITEMS</button></div><div class="grid">`;if(tab==='all')gear=game.inventory;h+=equipped?`<div class="card"><div class="eyebrow">EQUIPPED ${tab.toUpperCase()}</div><h3 class="${rarClass(equipped.rarity)}">${equipped.name}</h3><p>${equipped.rarity} · +${equipped.bonus} ${equipped.type==='weapon'?'attack':equipped.type==='armor'?'guard':'power'}</p></div>`:`<div class="card"><div class="eyebrow">${tab.toUpperCase()} SLOT</div><h3>Nothing equipped</h3><p>Find treasure in caches and from guardians.</p></div>`;if(!gear.length)h+=`<div class="card"><h3>Your pack is quiet</h3><p>Defeat guardians and explore caches for new gear.</p></div>`;gear.forEach((i,n)=>h+=`<div class="card"><h3 class="${rarClass(i.rarity)}">${i.name}</h3><p>${i.rarity} ${i.type} · +${i.bonus} · floor ${i.floor||1}</p><button onclick="window.equipItem(${game.inventory.indexOf(i)})">EQUIP</button></div>`);h+='</div>';$('#modalContent').innerHTML=h}
window.setTab=t=>{tab=t;renderInventory()};window.equipItem=i=>{let item=game.inventory[i];if(!item)return;game.equipment[item.type]=item;game.inventory.splice(i,1);renderInventory();updateUI();sound(260,.12,'triangle');toast(`${item.name} equipped`)};
