import json, socket, struct, urllib.request, time

def newtab(url):
 req=urllib.request.Request('http://localhost:9222/json/new?'+url,method='PUT')
 return json.loads(urllib.request.urlopen(req).read())
t=newtab('http://localhost:3002/index.html'); u=t['webSocketDebuggerUrl']; host=u.split('/')[2].split(':')[0];port=int(u.split('/')[2].split(':')[1]);path='/'+u.split('/',3)[3]
s=socket.create_connection((host,port));key='bW9ja2tleWZvcmNkcA=='
s.sendall((f'GET {path} HTTP/1.1\r\nHost: {host}:{port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n').encode());resp=s.recv(4096)
if b'101' not in resp: raise Exception(resp)
errs=[]
def send(obj):
 b=json.dumps(obj).encode();n=len(b);mask=b'1234';h=bytes([0x81,0x80|n]) if n<126 else bytes([0x81,0x80|126])+struct.pack('!H',n)
 s.sendall(h+mask+bytes(v^mask[i%4] for i,v in enumerate(b)))
def recv():
 h=s.recv(2); n=h[1]&127
 if n==126:n=struct.unpack('!H',s.recv(2))[0]
 data=b''
 while len(data)<n:data+=s.recv(n-len(data))
 if h[1]&128:
  m=s.recv(4);data=bytes(v^m[i%4] for i,v in enumerate(data))
 return json.loads(data)
def call(i,method,params={}):
 send({'id':i,'method':method,'params':params})
 while True:
  r=recv()
  if r.get('method') in ('Runtime.exceptionThrown','Log.entryAdded'):
   if r.get('method')=='Runtime.exceptionThrown':errs.append(r)
   elif r.get('params',{}).get('entry',{}).get('level')=='error':errs.append(r)
  if r.get('id')==i:return r
def ev(i,expr,awaitp=False):return call(i,'Runtime.evaluate',{'expression':expr,'returnByValue':True,'awaitPromise':awaitp})['result']['result'].get('value')
call(1,'Runtime.enable');call(2,'Log.enable');call(3,'Page.enable');time.sleep(1)
print('initial:',ev(4,"({start:document.querySelector('#startScreen').style.display,labels:[...document.querySelectorAll('.field label')].map(e=>e.textContent)})"))
print('spanish setup:',ev(5,"document.querySelector('#language').value='es';document.querySelector('#language').dispatchEvent(new Event('change'));({label:[...document.querySelectorAll('.field label')].map(e=>e.textContent),begin:document.querySelector('#startBtn').textContent,help:document.querySelector('.help').textContent.slice(0,30),htmlLang:document.documentElement.lang})"))
print('begin:',ev(6,"document.querySelector('#nameInput').value='<Aster>';document.querySelector('#classSelect').value='Arcanist';document.querySelector('#difficulty').value='Story';document.querySelector('#startBtn').click();({name:document.querySelector('#playerName').textContent,hp:document.querySelector('#hpText').textContent,objective:document.querySelector('#objective').textContent,job:document.querySelector('#classLine').textContent,mp:document.querySelector('#mpText').textContent})"))
print('status:',ev(7,"document.querySelector('#statusBtn').click();({title:document.querySelector('#modalTitle').textContent,points:document.querySelector('#modalContent').textContent.includes('UNSPENT POINTS')})"))
ev(8,'window.closeModal()')
print('settings:',ev(9,"document.querySelector('#settingsBtn').click();({title:document.querySelector('#modalTitle').textContent,language:document.querySelector('#langSelect').value,help:document.querySelector('#modalContent').textContent.slice(-130)})"))
print('switch language:',ev(10,"window.setLanguage('en');({objective:document.querySelector('#objective').textContent,bag:document.querySelector('#inventoryBtn').textContent,title:document.querySelector('#modalTitle').textContent,lang:document.documentElement.lang})"))
# Let autosave timer fire, then check data before reloading.
time.sleep(5.5)
save=ev(11,"JSON.parse(localStorage.getItem('ascent-save')||'null')")
print('autosave:',{'exists':bool(save),'floor':save['game']['floor'] if save else None,'name':save['game']['name'] if save else None})
call(12,'Page.navigate',{'url':'http://localhost:3002/index.html'});time.sleep(1)
print('continue button:',ev(13,"({display:getComputedStyle(document.querySelector('#continueBtn')).display,text:document.querySelector('#continueBtn').textContent})"))
print('continued:',ev(14,"document.querySelector('#continueBtn').click();({start:getComputedStyle(document.querySelector('#startScreen')).display,name:document.querySelector('#playerName').textContent,job:document.querySelector('#classLine').textContent,lang:document.documentElement.lang,floor:document.querySelector('#floorLabel').textContent})"))
print('runtime errors:',len(errs),json.dumps(errs[:2])[:1000])
s.close()

