 function gainXp(n){game.xp+=n;while(game.xp>=game.nextXp){game.xp-=game.nextXp;game.level++;game.nextXp=Math.floor(game.nextXp*1.32);game.points+=3;game.maxHp+=12;game.maxMp+=5;game.hp=game.maxHp;game.mp=game.maxMp;toast(`LEVEL ${game.level} · 3 STAT POINTS`);log(`Level up! Three points to distribute.`);sound(540,.2,'triangle')}updateUI()}
 function dropLoot(){let def=pick(['weapon','armor','relic']),r=rarity[Math.min(4,Math.floor(Math.random()*5+game.floor/32))],item={...pick(definitions[def]),type:def,rarity:r,floor:game.floor};item.bonus=Math.floor(item.bonus*(1+game.floor*.023));game.inventory.push(item);game.gold+=8+game.floor*2;toast(`${item.rarity} ${item.name} found`);log(`Found ${item.name} · ${r}`);sound(610,.12,'triangle')}
 function kill(e){game.entities=game.entities.filter(x=>x!==e);game.kills++;let xp=e.type==='boss'?120+game.floor*3:24+game.floor;gainXp(xp);game.gold+=e.type==='boss'?90:12;log(`${e.name} defeated · +${xp} XP`);if(e.type==='boss'||Math.random()<.42)dropLoot();updateUI()}
 function attack(){if(!started||paused||modal||game.gameover||game.attackCd>0)return;game.attackCd=.42;let target=null,best=2.2;for(let e of game.entities){if(e.type!=='enemy'&&e.type!=='boss')continue;let dx=e.x-game.x,dy=e.y-game.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-game.ang;a=Math.atan2(Math.sin(a),Math.cos(a));if(d<best&&Math.abs(a)<.46){target=e;best=d}}sound(95,.07,'triangle',.045);if(target){let st=mobStats(),crit=Math.random()*100<st.crit,dmg=Math.round(st.damage*(crit?1.8:1));target.hp-=dmg;target.flash=.18;log(`${crit?'Critical! ':''}${target.name} −${dmg}`);if(target.hp<=0)kill(target);else sound(250,.05,'square',.02)}else{toast('Strike missed');}}
