 function interact(){if(!started||modal||paused)return;let target=null,dist=2;for(let e of game.entities){let d=Math.hypot(e.x-game.x,e.y-game.y),a=Math.atan2(e.y-game.y,e.x-game.x)-game.ang;a=Math.atan2(Math.sin(a),Math.cos(a));if(d<dist&&Math.abs(a)<.85){target=e;dist=d}}if(!target){toast('Nothing within reach');return}if(target.type==='npc')openNpc(target);else if(target.type==='chest'){if(target.opened){toast('The cache is empty');return}target.opened=true;game.gold+=30+game.floor*5;dropLoot();toast('Cache opened · shards secured');log('A sealed cache yielded treasure.');updateUI()}else if(target.type==='stairs'){if(game.entities.some(e=>e.type==='enemy'||e.type==='boss')){toast('The stair is sealed. Defeat every guardian.');return}if(game.floor===100){showEnd(true);return}game.floor++;if(game.floor%10===1)game.hp=Math.min(game.maxHp,game.hp+22);buildFloor();toast(`Ascending to floor ${game.floor}`);sound(330,.22,'sine')}}
 function openNpc(npc){const safeName=escapeHTML(game.name);let greeting=game.floor===1?`“${safeName}, is it? The tower listens. I trade in what it leaves behind. Every floor has a keeper, and every keeper has a pattern. Ask a question—or trade your shards.”`:`“Still climbing, ${safeName}? I remember every face that passes. The tower changes its tricks, never its hunger. Keep your guard high.”`;if(game.hp<game.maxHp*.4)greeting+=' “You are bleeding. A tonic may keep you standing.”';else if(game.equipment.armor)greeting+=' “That armor suits you. You have learned to survive.”';else if(game.floor%10===0)greeting+=' “A guardian waits nearby. Watch its wind-up before you commit.”';if(lang==='es')greeting=`«${safeName}, ¿sigues subiendo? La torre cambia sus trucos, nunca su hambre. Mantén la guardia alta. Puedo intercambiar equipo por fragmentos.»`;openModal('dialogue',`<div class="eyebrow">${npc.name.toUpperCase()} · LIVING MEMORY</div><div class="dialogue">${greeting}</div><div class="grid"><div class="card"><h3>Buy a field tonic</h3><p>Restore 45 vitality. Cost: 25 shards.</p><button onclick="buyTonic()">BUY · 25 ✦</button></div><div class="card"><h3>Ask for a hint</h3><p>${game.entities.some(e=>e.type==='boss')?'Bosses punish predictable strikes. Use your arcane pulse when they close in.':'Search the corners; a sealed cache waits on each floor.'}</p><button onclick="window.toast('The scribe has shared a hint.')">LISTEN</button></div><div class="card"><h3>Trade a random relic</h3><p>Spend 55 shards for a relic with power scaled to this floor.</p><button onclick="buyRelic()">TRADE · 55 ✦</button></div><div class="card"><h3>Leave</h3><p>The tower does not wait forever.</p><button onclick="closeModal()">GOODBYE</button></div></div>`)}
 window.buyTonic=()=>{if(game.gold<25){toast('Not enough shards');return}game.gold-=25;game.hp=Math.min(game.maxHp,game.hp+45);updateUI();sound(520,.15,'sine');toast('Tonic restores vitality')};window.buyRelic=()=>{if(game.gold<55){toast('Not enough shards');return}game.gold-=55;let i={...pick(definitions.relic),type:'relic',rarity:pick(rarity),floor:game.floor};i.bonus=Math.floor(i.bonus*(1+game.floor*.023));game.inventory.push(i);updateUI();sound(600,.15,'triangle');openInventory()};
 function raycast(angle){let rx=Math.cos(angle),ry=Math.sin(angle),mx=game.x|0,my=game.y|0,ddx=Math.abs(1/(rx||1e-8)),ddy=Math.abs(1/(ry||1e-8)),sx=rx<0?-1:1,sy=ry<0?-1:1,sdx=(rx<0?game.x-mx:mx+1-game.x)*ddx,sdy=(ry<0?game.y-my:my+1-game.y)*ddy,side=0;for(let i=0;i<32;i++){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(game.map[my]?.[mx])return{d:Math.max(.05,side===0?sdx-ddx:sdy-ddy),side,mx,my}}return{d:20,side:0,mx,my}}

